// @dotasn/wasm: the DotAsn .NET runtime compiled to WebAssembly with NativeAOT-LLVM.
//
// A schema (generated by `asn1 generate-typescript` as dotasn-schema.ts, or by `asn1 generate-schema`) describes the
// types; values cross into the module in the DotAsn JSON value notation. The TypeScript types and descriptors
// generated alongside (with @dotasn/runtime) give the rules typed values.

import { Asn1Error, Asn1NotationError, fromNotation, resolve, toNotation, type Asn1Type } from '@dotasn/runtime';
import createDotAsnModule, { type DotAsnModule, type DotAsnModuleOptions } from '../lib/dotasn.js';
import { Asn1DecodeError, Asn1EncodeError, Asn1UnsupportedError, type DecodeErrorKind } from './errors.ts';

export { Asn1DecodeError, Asn1EncodeError, Asn1UnsupportedError, type DecodeErrorKind } from './errors.ts';

/** The encoding rules of the WebAssembly runtime. */
export type RuleName = 'BER' | 'CER' | 'DER' | 'APER' | 'UPER' | 'OER' | 'COER' | 'JER' | 'XER' | 'CXER';

export const ruleNames: readonly RuleName[] = ['BER', 'CER', 'DER', 'APER', 'UPER', 'OER', 'COER', 'JER', 'XER', 'CXER'];

/** Where to find dotasn.wasm when the default (next to the loader, resolved with import.meta.url) does not work. */
export interface LoadOptions {
  /** The module's URL or path, its bytes, or a compiled WebAssembly.Module. */
  readonly wasm?: string | URL | ArrayBuffer | Uint8Array | WebAssembly.Module;
}

/** Decoding options (those of the .NET runtime's Asn1DecodingOptions). */
export interface DecodeOptions {
  /** Reject octets after the encoded value (default true). */
  readonly rejectTrailingData?: boolean;
  /** Maximum nesting depth (default 128). */
  readonly maxDepth?: number;
  /** Maximum number of elements of a SEQUENCE OF/SET OF (default 1,000,000). */
  readonly maxCollectionCount?: number;
  /** Maximum length of strings in octets (default 16 MiB). */
  readonly maxStringLength?: number;
  /** Check constraints after decoding (default true). */
  readonly validateConstraints?: boolean;
}

/** An encoding rule of a loaded schema, for values described by generated descriptors. */
export interface EncodingRule {
  /** The rule's name: BER, CER, DER, APER, UPER, OER, COER, JER, XER or CXER. */
  readonly name: RuleName;
  encode<T>(type: Asn1Type<T>, value: T): Uint8Array;
  decode<T>(type: Asn1Type<T>, data: Uint8Array, options?: DecodeOptions): T;
}

/** A constraint violation found by {@link DotAsn.validate}. */
export interface ValidationError {
  readonly path: string;
  readonly message: string;
}

/** A schema loaded into the WebAssembly runtime. */
export interface DotAsn {
  readonly ber: EncodingRule;
  readonly cer: EncodingRule;
  readonly der: EncodingRule;
  readonly aper: EncodingRule;
  readonly uper: EncodingRule;
  readonly oer: EncodingRule;
  readonly coer: EncodingRule;
  readonly jer: EncodingRule;
  readonly xer: EncodingRule;
  readonly cxer: EncodingRule;
  /** The qualified names (Module.Type) of the schema's types. */
  readonly typeNames: readonly string[];
  /** The rule with this name. */
  rule(name: RuleName): EncodingRule;
  /** Encodes a value given in the JSON value notation, by type name (qualified, or unqualified if unambiguous). */
  encodeNotation(type: string, rule: RuleName, value: unknown): Uint8Array;
  /** Decodes to the JSON value notation, by type name. */
  decodeNotation(type: string, rule: RuleName, data: Uint8Array, options?: DecodeOptions): unknown;
  /** Checks a value against the type's constraints; an empty array means valid. */
  validate<T>(type: Asn1Type<T> | string, value: T): ValidationError[];
  /** Releases the schema inside the module. */
  dispose(): void;
}

let shared: Promise<DotAsnModule> | undefined;

/** Instantiates the WebAssembly module (once; later calls return the same instance unless options are given). */
function loadModule(options?: LoadOptions): Promise<DotAsnModule> {
  if (options?.wasm === undefined) {
    return (shared ??= createDotAsnModule());
  }

  const wasm = options.wasm;
  const moduleOptions: DotAsnModuleOptions =
    wasm instanceof WebAssembly.Module
      ? { instantiateWasm: (imports, success) => WebAssembly.instantiate(wasm, imports).then(instance => success(instance, wasm)) }
      : wasm instanceof ArrayBuffer || wasm instanceof Uint8Array
        ? { wasmBinary: wasm }
        : { locateFile: () => wasm.toString() };
  return createDotAsnModule(moduleOptions);
}

/**
 * Loads a schema into the WebAssembly runtime.
 *
 * ```ts
 * import { loadDotAsn } from '@dotasn/wasm';
 * import { schema } from './generated/dotasn-schema.js';
 * import { Heartbeat } from './generated/TelemetryProtocol.js';
 *
 * const asn1 = await loadDotAsn(schema);
 * const bytes = asn1.uper.encode(Heartbeat, { sequenceNumber: 7, uptimeSeconds: 4_000_000_000 });
 * ```
 */
export async function loadDotAsn(schema: string | object, options?: LoadOptions): Promise<DotAsn> {
  const module = await loadModule(options);
  return new Session(module, typeof schema === 'string' ? schema : JSON.stringify(schema));
}

const utf8 = new TextEncoder();
const text = new TextDecoder();

class Session implements DotAsn {
  private readonly m: DotAsnModule;
  private handle: number;
  private readonly rules = new Map<RuleName, EncodingRule>();
  readonly typeNames: readonly string[];

  constructor(module: DotAsnModule, schema: string) {
    this.m = module;
    this.handle = Number(text.decode(this.call(() => module._dotasn_load_schema(...this.args(schema)))));
    this.typeNames = JSON.parse(text.decode(this.call(() => module._dotasn_type_names(this.handle)))) as string[];
  }

  get ber(): EncodingRule { return this.rule('BER'); }
  get cer(): EncodingRule { return this.rule('CER'); }
  get der(): EncodingRule { return this.rule('DER'); }
  get aper(): EncodingRule { return this.rule('APER'); }
  get uper(): EncodingRule { return this.rule('UPER'); }
  get oer(): EncodingRule { return this.rule('OER'); }
  get coer(): EncodingRule { return this.rule('COER'); }
  get jer(): EncodingRule { return this.rule('JER'); }
  get xer(): EncodingRule { return this.rule('XER'); }
  get cxer(): EncodingRule { return this.rule('CXER'); }

  rule(name: RuleName): EncodingRule {
    let rule = this.rules.get(name);
    if (rule === undefined) {
      const session = this;
      rule = {
        name,
        encode<T>(type: Asn1Type<T>, value: T): Uint8Array {
          return session.encodeNotation(resolve(type).name, name, toNotation(type, value));
        },
        decode<T>(type: Asn1Type<T>, data: Uint8Array, options?: DecodeOptions): T {
          return fromNotation(type, session.decodeNotation(resolve(type).name, name, data, options));
        },
      };
      this.rules.set(name, rule);
    }

    return rule;
  }

  encodeNotation(type: string, rule: RuleName, value: unknown): Uint8Array {
    const json = JSON.stringify(value);
    return this.call(() => this.m._dotasn_encode(this.live(), ...this.args(type), ...this.args(rule), ...this.args(json)));
  }

  decodeNotation(type: string, rule: RuleName, data: Uint8Array, options?: DecodeOptions): unknown {
    const json = options === undefined ? '' : JSON.stringify(options);
    const result = this.call(() => this.m._dotasn_decode(this.live(), ...this.args(type), ...this.args(rule), ...this.args(data), ...this.args(json)));
    return JSON.parse(text.decode(result));
  }

  validate<T>(type: Asn1Type<T> | string, value: T): ValidationError[] {
    const [name, notation] = typeof type === 'string' ? [type, value] : [resolve(type).name, toNotation(type, value)];
    const json = JSON.stringify(notation);
    return JSON.parse(text.decode(this.call(() => this.m._dotasn_validate(this.live(), ...this.args(name), ...this.args(json))))) as ValidationError[];
  }

  dispose(): void {
    if (this.handle > 0) {
      this.m._dotasn_unload_schema(this.handle);
      this.handle = 0;
    }
  }

  private live(): number {
    if (this.handle <= 0) {
      throw new Asn1Error('the schema has been disposed', '');
    }

    return this.handle;
  }

  private readonly pending: number[] = [];

  /** Copies an argument into module memory (freed after the call); returns [pointer, length]. */
  private args(value: string | Uint8Array): [number, number] {
    const bytes = typeof value === 'string' ? utf8.encode(value) : value;
    const pointer = this.m._dotasn_alloc(bytes.length);
    this.m.HEAPU8.set(bytes, pointer);
    this.pending.push(pointer);
    return [pointer, bytes.length];
  }

  /** Runs an export and returns its result bytes, or throws the error it reported. */
  private call(invoke: () => number): Uint8Array {
    let status: number;
    try {
      status = invoke();
    } finally {
      for (const pointer of this.pending.splice(0)) {
        this.m._dotasn_free(pointer);
      }
    }

    // HEAPU8 may have been replaced by memory growth during the call, so read it afresh.
    const start = this.m._dotasn_result_ptr();
    const result = this.m.HEAPU8.slice(start, start + this.m._dotasn_result_len());
    if (status !== 0) {
      throw toError(JSON.parse(text.decode(result)) as WasmError);
    }

    return result;
  }
}

interface WasmError {
  readonly type: string;
  readonly message: string;
  readonly kind?: string;
  readonly path?: string;
  readonly bitOffset?: number;
}

const decodeKinds: Record<string, DecodeErrorKind> = {
  Truncated: 'truncated',
  InvalidTag: 'invalidTag',
  InvalidLength: 'invalidLength',
  NonCanonical: 'nonCanonical',
  Malformed: 'malformed',
  ConstraintViolation: 'constraintViolation',
  LimitExceeded: 'limitExceeded',
  TrailingData: 'trailingData',
  Overflow: 'limitExceeded',
  Unsupported: 'unsupported',
};

function toError(e: WasmError): Asn1Error {
  const path = e.path ?? '';
  switch (e.type) {
    case 'decode':
      return new Asn1DecodeError(decodeKinds[e.kind ?? ''] ?? 'malformed', e.message, path, e.bitOffset ?? -1);
    case 'encode':
    case 'constraint':
      return new Asn1EncodeError(e.message, path);
    case 'notation':
      return new Asn1NotationError(e.message, path);
    case 'unsupported':
      return new Asn1UnsupportedError(e.message, path);
    default:
      return new Asn1Error(e.message, path);
  }
}
